def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    groups = []  # Initialize a list to store separated groups
    group = ""  # Initialize an empty string to store the current group

    for char in paren_string:
        if char == "(":
            if group:  # Check if the group is not empty
                groups.append(group)  # Add the current group to the list
            group = "("  # Start a new group
        elif char == ")":
            group += ")"  # Add the closing parenthesis to the current group
            groups.append(group)  # Add the complete group to the list
            group = ""  # Reset the current group

    return groups
